    elif rows == 3 and cols % 3 == 0:
        nrows, ncols = 1, cols // 3
    else:
        # fallback: treat the whole grid as a single block if possible
        if rows == 3 and cols == 3:
            nrows, ncols = 1, 1
        else:
            raise ValueError("Grid size is not compatible with 3×3 blocks")

    blocks = []
    masks = []

    for i in range(nrows):
        for j in range(ncols):
            # Extract the 3×3 sub‑grid
            block = [grid[i * 3 + r][j * 3:(j + 1) * 3] for r in range(3)]
            blocks.append(block)
            # Create a binary mask: 1 for non‑zero, 0 for zero
            mask = tuple(1 if cell != 0 else 0 for row in block for cell in row)
            masks.append(mask)

    # Find the mask that occurs only once
    from collections import Counter
    counts = Counter(masks)
    odd_mask = next(m for m, c in counts.items() if c == 1)

    # Return the block with the unique mask
    for block, mask in zip(blocks, masks):
        if mask == odd_mask:
